package com.l4d.infected.client;

import com.l4d.infected.entity.CommonInfected;
import net.minecraft.client.model.geom.ModelPart;

import static com.l4d.infected.client.Anim.*;

/**
 * model spec: assets/l4dinfected/models/entity/common.json (generated by tools/tex_common.py).
 * Jointed humanoid (hip pivot, elbows, knees, jaw, cloth flaps). Base of every uncommon model:
 * idle limping shamble (lolling head, swaying arms) blended into an aggro sprint, a vault pose while airborne,
 * and the crafted SLAM / LUNGE / STUMBLE actions. Poses are written as keyframe tables blended over the
 * locomotion pose by an envelope, so every action eases in, strikes, and settles back.
 */
public class CommonModel<T extends CommonInfected> extends InfectedModel<T> {
    protected ModelPart body, head, ra, la, rf, lf, rl, ll, rs, ls;
    protected float runAmt, lookX, lookY, headZ;

    public CommonModel(ModelPart root) { this(root, "common"); }
    protected CommonModel(ModelPart root, String spec) {
        super(root, spec);
        body = part("body"); head = part("head"); ra = part("right_arm"); la = part("left_arm");
        rf = part("right_forearm"); lf = part("left_forearm"); rl = part("right_leg"); ll = part("left_leg");
        rs = part("right_shin"); ls = part("left_shin");
    }

    static float sin(float x) { return (float) Math.sin(x); }
    static float cos(float x) { return (float) Math.cos(x); }

    /** lowers the hips (and both legs) by d model units. */
    protected void drop(float d) { body.y += d; rl.y += d; ll.y += d; }
    /** blend a part's rotation towards (x,y,z) by w. */
    protected static void to(ModelPart p, float w, float x, float y, float z) {
        p.xRot = lerp(p.xRot, x, w); p.yRot = lerp(p.yRot, y, w); p.zRot = lerp(p.zRot, z, w);
    }
    /** keyframe value at progress p. */
    protected static float k(float p, float[] ts, float... vs) { return keys(p, ts, vs); }

    @Override
    protected void locomotion() {
        float s = limbAmt, c = limb * 0.6662f, br = sin(age * 0.09f);
        runAmt = lerp(ent.runO, ent.run, pt);
        lookX = head.xRot; lookY = head.yRot; headZ = head.zRot;
        shamble(s, c, br);
        if (runAmt > 0.01f) {
            // store the shamble pose, compute the run pose, blend
            float[] a = snap();
            sprint(s, c, br);
            float[] b = snap();
            for (int i = 0; i < a.length; i++) a[i] = lerp(a[i], b[i], runAmt);
            restore(a);
        }
        if (!ent.onGround() && !ent.isInWater() && !ent.isPassenger() && ent.action() == 0) vault();
        float fl = sin(age * 0.6f) * 0.15f * s;
        part("flap_front").xRot = -0.05f - 0.35f * s * runAmt + fl;
        part("flap_back").xRot = 0.1f + 0.9f * s + 0.2f * sin(age * 0.7f) * s;
        part("jaw").xRot = lerp(0.08f + 0.1f * Math.max(0, sin(age * 0.13f)), 0.3f + 0.3f * Math.abs(sin(age * 0.35f)), runAmt);
    }

    private ModelPart[] chain() { return new ModelPart[]{body, head, ra, la, rf, lf, rl, ll, rs, ls}; }
    private float[] snap() {
        ModelPart[] ps = chain(); float[] r = new float[ps.length * 4];
        for (int i = 0; i < ps.length; i++) { r[i * 4] = ps[i].xRot; r[i * 4 + 1] = ps[i].yRot; r[i * 4 + 2] = ps[i].zRot; r[i * 4 + 3] = ps[i].y; }
        return r;
    }
    private void restore(float[] r) {
        ModelPart[] ps = chain();
        for (int i = 0; i < ps.length; i++) { ps[i].xRot = r[i * 4]; ps[i].yRot = r[i * 4 + 1]; ps[i].zRot = r[i * 4 + 2]; ps[i].y = r[i * 4 + 3]; }
    }

    /** wandering: right leg drags stiff (limp), head lolls, arms dangle and sway behind the step. */
    protected void shamble(float s, float c, float br) {
        float sw = cos(c);
        body.xRot = 0.18f + 0.03f * br;
        body.zRot = 0.05f + 0.06f * sw * s;
        body.yRot = 0.08f * sw * s;
        body.y += Math.abs(sw) * 0.6f * s;
        rl.xRot = sw * 0.5f * s; rs.xRot = 0.08f * s;
        ll.xRot = -sw * 0.9f * s; ls.xRot = (0.1f + 0.8f * Math.max(0, sin(c + 3.14f))) * s;
        rl.zRot = 0.05f; ll.zRot = -0.03f;
        head.xRot = lookX * 0.5f + 0.28f + 0.1f * sin(age * 0.031f);
        head.yRot = lookY * 0.6f + 0.18f * sin(age * 0.023f);
        head.zRot = headZ + 0.22f * sin(age * 0.04f);
        ra.xRot = -0.15f - sw * 0.35f * s + 0.05f * br; ra.zRot = 0.1f + 0.05f * sin(age * 0.07f); ra.yRot = 0;
        la.xRot = -0.45f + sw * 0.25f * s - 0.04f * br; la.zRot = -0.12f; la.yRot = 0;
        rf.xRot = -0.2f - 0.15f * sin(c - 0.6f) * s; lf.xRot = -0.65f + 0.1f * br;
    }

    /** aggro sprint: hard lean, pumping bent arms, high knees, head up at the prey. */
    protected void sprint(float s, float c, float br) {
        float sw = cos(c);
        body.xRot = 0.15f + 0.3f * s + 0.04f * br;
        body.yRot = sw * 0.2f * s; body.zRot = 0;
        head.xRot = lookX + 0.05f - 0.25f * s; head.yRot = lookY; head.zRot = headZ * 0.5f;
        rl.xRot = sw * 1.25f * s; ll.xRot = -sw * 1.25f * s;
        rs.xRot = (0.2f + 1.0f * Math.max(0, sin(c))) * s; ls.xRot = (0.2f + 1.0f * Math.max(0, -sin(c))) * s;
        rl.zRot = 0; ll.zRot = 0;
        ra.xRot = -0.7f - sw * 1.0f * s; la.xRot = -0.7f + sw * 1.0f * s;
        ra.zRot = 0.25f; la.zRot = -0.25f;
        rf.xRot = -0.8f - 0.4f * Math.max(0, sw); lf.xRot = -0.8f - 0.4f * Math.max(0, -sw);
    }

    /** airborne (ledge hop / fall): knees tucked, arms up for balance. */
    protected void vault() {
        float f = sin(age * 0.8f) * 0.25f;
        body.xRot = 0.3f;
        rl.xRot = -1.0f; rs.xRot = 1.5f; ll.xRot = -0.6f; ls.xRot = 1.1f;
        ra.xRot = -1.9f + f; la.xRot = -1.6f - f; ra.zRot = 0.5f; la.zRot = -0.5f;
        rf.xRot = -0.3f; lf.xRot = -0.3f;
    }

    @Override
    protected void action(int id) {
        float p = ent.actionProgress(pt);
        switch (id) {
            case CommonInfected.SLAM -> slam(p);
            case CommonInfected.LUNGE -> lunge(p);
            case CommonInfected.STUMBLE -> stumble(p);
            default -> {}
        }
    }

    static final float[] SLAM_T = {0, .38f, .5f, .6f, 1};
    /** two-handed overhead: rear up hands behind head (leaning back), hammer both fists down on frame 11, settle. */
    protected void slam(float p) {
        float w = k(p, new float[]{0, .12f, .72f, 1}, 0, 1, 1, 0);
        float ax = k(p, SLAM_T, -0.3f, -2.9f, -0.5f, -0.35f, -0.35f);
        float fx = k(p, SLAM_T, -0.3f, -1.3f, -0.1f, -0.2f, -0.2f);
        float az = k(p, SLAM_T, 0.1f, 0.25f, -0.15f, -0.1f, 0.1f);
        to(ra, w, ax, 0, az); to(la, w, ax, 0, -az);
        to(rf, w, fx, 0, 0); to(lf, w, fx, 0, 0);
        to(body, w, k(p, SLAM_T, 0.15f, -0.3f, 0.6f, 0.7f, 0.3f), 0, 0);
        drop(w * k(p, SLAM_T, 0, -0.5f, 1.5f, 1.8f, 0));
        head.xRot += w * k(p, SLAM_T, 0, -0.5f, 0.1f, 0.05f, 0);
        to(rl, w, k(p, SLAM_T, 0, 0.15f, -0.55f, -0.55f, 0), 0, 0);
        to(rs, w, k(p, SLAM_T, 0, 0.2f, 0.7f, 0.7f, 0), 0, 0);
        to(ll, w, k(p, SLAM_T, 0, -0.1f, 0.35f, 0.35f, 0), 0, 0);
        to(ls, w, k(p, SLAM_T, 0, 0.1f, 0.3f, 0.3f, 0), 0, 0);
        part("jaw").xRot = lerp(part("jaw").xRot, k(p, SLAM_T, 0.1f, 0.6f, 0.15f, 0.2f, 0.1f), w);
    }

    static final float[] LUNGE_T = {0, .3f, .38f, .6f, .75f, .85f, 1};
    /** crouch & coil (arms swung back) -> spring (frame 7) arms thrown forward -> tuck in air -> absorb landing -> rise. */
    protected void lunge(float p) {
        float w = k(p, new float[]{0, .08f, .85f, 1}, 0, 1, 1, 0);
        drop(w * k(p, LUNGE_T, 0, 3.5f, -0.5f, -0.5f, 3f, 2f, 0));
        to(body, w, k(p, LUNGE_T, 0.2f, 0.75f, 0.3f, 0.15f, 0.6f, 0.5f, 0.2f), 0, 0);
        head.xRot += w * k(p, LUNGE_T, 0, -0.55f, -0.4f, -0.3f, -0.3f, -0.1f, 0);
        to(rl, w, k(p, LUNGE_T, 0, -0.9f, 0.5f, 0.3f, -0.9f, -0.6f, 0), 0, 0.05f);
        to(ll, w, k(p, LUNGE_T, 0, -0.7f, 0.7f, -0.2f, -1.0f, -0.6f, 0), 0, -0.05f);
        to(rs, w, k(p, LUNGE_T, 0, 1.55f, 0.2f, 0.8f, 1.55f, 1.1f, 0), 0, 0);
        to(ls, w, k(p, LUNGE_T, 0, 1.4f, 0.1f, 1.3f, 1.7f, 1.1f, 0), 0, 0);
        float ax = k(p, LUNGE_T, -0.5f, 0.6f, -1.9f, -1.7f, -1.2f, -0.9f, -0.5f);
        float az = k(p, LUNGE_T, 0.1f, 0.3f, 0.35f, 0.45f, 0.25f, 0.2f, 0.1f);
        to(ra, w, ax, 0, az); to(la, w, ax, 0, -az);
        float fx = k(p, LUNGE_T, -0.4f, -0.2f, -0.2f, -0.6f, -0.9f, -0.6f, -0.4f);
        to(rf, w, fx, 0, 0); to(lf, w, fx, 0, 0);
        part("jaw").xRot = lerp(part("jaw").xRot, k(p, LUNGE_T, 0.2f, 0.3f, 0.6f, 0.7f, 0.3f, 0.2f, 0.2f), w);
    }

    static final float[] STUMBLE_T = {0, .25f, .5f, .7f, 1};
    /** toe catches: pitch forward, arms fling out, a hard catch-step, regain balance. */
    protected void stumble(float p) {
        float w = k(p, new float[]{0, .1f, .8f, 1}, 0, 1, 1, 0);
        drop(w * k(p, STUMBLE_T, 0, 2f, 2.5f, 1f, 0));
        to(body, w, k(p, STUMBLE_T, 0.4f, 0.95f, 0.8f, 0.5f, 0.35f), 0, k(p, STUMBLE_T, 0, 0.2f, -0.1f, 0, 0));
        head.xRot += w * k(p, STUMBLE_T, 0, -0.5f, -0.6f, -0.2f, 0);
        to(rl, w, k(p, STUMBLE_T, 0, 0.7f, -0.8f, -0.4f, 0), 0, 0);
        to(rs, w, k(p, STUMBLE_T, 0.3f, 0.9f, 1.0f, 0.5f, 0.3f), 0, 0);
        to(ll, w, k(p, STUMBLE_T, 0, -0.4f, 0.3f, 0.1f, 0), 0, 0);
        to(ls, w, k(p, STUMBLE_T, 0.3f, 0.4f, 1.2f, 0.4f, 0.3f), 0, 0);
        float ax = k(p, STUMBLE_T, -0.5f, -1.3f, -1.6f, -0.9f, -0.5f), az = k(p, STUMBLE_T, 0.2f, 0.8f, 0.6f, 0.3f, 0.2f);
        to(ra, w, ax, 0, az); to(la, w, ax * 0.8f, 0, -az * 1.2f);
        float fx = k(p, STUMBLE_T, -0.5f, -0.2f, -0.1f, -0.4f, -0.5f);
        to(rf, w, fx, 0, 0); to(lf, w, fx, 0, 0);
    }
}
